 	}
-	*value = cbor_get_uint8(item);
+	tmp = cbor_get_int(item);
+	if (tmp > G_MAXUINT8) {
+		g_set_error(error,
+			    FWUPD_ERROR,
+			    FWUPD_ERROR_INVALID_DATA,
